/* ===== v2 admin A: chart tabs, categories + suggestions, admins, roles ===== */
/* generic searchable combobox */
const COMBO={};
function comboHtml(id,cfg){COMBO[id]={idx:-1,recent:[],...cfg};const sel=cfg.items.find(i=>i.id===cfg.value);
 return `<div class="combo" data-combo="${id}"><label class="lbl small" for="cb_${id}">${t(cfg.label)}</label><div class="searchbar" style="margin-top:6px">${ic('search',18)}<input id="cb_${id}" role="combobox" aria-expanded="false" aria-controls="lb_${id}" aria-autocomplete="list" autocomplete="off" data-in="combo" data-cid="${id}" placeholder="${esc(sel?sel.label:t(cfg.placeholder||'Type to search'))}"><button type="button" class="iconbtn" data-act="comboOpen" data-cid="${id}" aria-label="${t('Show options')}">${ic('cd',18)}</button></div>${sel?`<div class="small t2" style="margin-top:4px">${t('Selected')}: <b>${esc(sel.label)}</b></div>`:''}<ul id="lb_${id}" role="listbox" hidden></ul></div>`}
function comboShow(id,q){const c=COMBO[id],ul=$('#lb_'+id),inp=$('#cb_'+id);if(!ul)return;q=(q||'').toLowerCase();let items=c.items.filter(i=>!q||i.label.toLowerCase().includes(q)||(i.sub||'').toLowerCase().includes(q));const rec=!q?c.recent.map(r=>c.items.find(i=>i.id===r)).filter(Boolean):[];c.flat=[];let h='';
 const add=(grp,arr)=>{if(!arr.length)return;h+=`<li class="grp" role="presentation">${t(grp)}</li>`;arr.forEach(i=>{const n=c.flat.length;c.flat.push(i);h+=`<li role="option" id="lb_${id}_${n}" aria-selected="${n===c.idx}" data-act="comboPick" data-cid="${id}" data-id="${esc(i.id)}">${esc(i.label)}${i.sub?` <span class="xs muted">· ${esc(i.sub)}</span>`:''}</li>`})};
 add('Recent',rec);const groups=[...new Set(items.map(i=>i.group||''))];groups.forEach(g=>add(g||'All',items.filter(i=>(i.group||'')===g).slice(0,q?40:8)));if(!c.flat.length)h=`<li role="presentation" style="cursor:default">${t('No results')}</li>`;ul.innerHTML=h;ul.hidden=false;inp.setAttribute('aria-expanded','true')}
INP.combo=(v,el)=>{COMBO[el.dataset.cid].idx=-1;comboShow(el.dataset.cid,v)};
A.comboOpen=el=>{const id=el.dataset.cid,ul=$('#lb_'+id);if(ul.hidden){COMBO[id].idx=-1;comboShow(id,'');$('#cb_'+id).focus()}else{ul.hidden=true}};
A.comboPick=el=>{const c=COMBO[el.dataset.cid];c.recent=[el.dataset.id,...c.recent.filter(x=>x!==el.dataset.id)].slice(0,4);S.cmRecent=S.cmRecent||{};S.cmRecent[el.dataset.cid]=c.recent;c.onPick(el.dataset.id)};
document.addEventListener('keydown',e=>{const inp=e.target.closest&&e.target.closest('.combo input');if(!inp)return;const id=inp.dataset.cid,c=COMBO[id];if(!c)return;const ul=$('#lb_'+id);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(ul.hidden)comboShow(id,inp.value);c.idx=clamp(c.idx+(e.key==='ArrowDown'?1:-1),0,Math.max(0,c.flat.length-1));$$('#lb_'+id+' [role=option]').forEach((li,i)=>li.setAttribute('aria-selected',i===c.idx));inp.setAttribute('aria-activedescendant','lb_'+id+'_'+c.idx);const a=$('#lb_'+id+'_'+c.idx);a&&a.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&c.idx>=0&&c.flat[c.idx]){e.preventDefault();A.comboPick({dataset:{cid:id,id:c.flat[c.idx].id}})}else if(e.key==='Escape'&&!ul.hidden){e.stopPropagation();ul.hidden=true;inp.setAttribute('aria-expanded','false')}},true);
document.addEventListener('click',e=>{if(!e.target.closest('.combo'))$$('.combo ul').forEach(u=>u.hidden=true)});
/* ---- A1 chart card ---- */
UI.xc={tab:'graph',metric:'orders',range:'7d',city:'all',load:false};
const XM=[['orders','Orders'],['revenue','Revenue'],['deliveries','Deliveries']],XR=[['7d','Last 7 days'],['30d','Last 30 days'],['90d','Last 90 days']];
const xfmt=v=>UI.xc.metric==='revenue'?inr(Math.round(v)):String(Math.round(v));
function xData(){const c=UI.xc,n=c.range==='7d'?7:c.range==='30d'?15:13;if(c.city!=='all'&&c.city!=='padrauna')return[];const base={orders:42,revenue:46000,deliveries:34}[c.metric]*(c.city==='all'?1:.9),lab=i=>c.range==='7d'?lastDays(7)[i]:c.range==='30d'?'D'+(i*2+1):'W'+(i+1);let prev=base,out=[];for(let i=0;i<n;i++){const o=prev,r=Math.sin((i+2)*(c.metric.length+.7))*.5+Math.cos(i*1.7+c.range.length)*.35,cl=Math.max(base*.4,o*(1+r*.2)),hi=Math.max(o,cl)*(1+.05+.04*Math.abs(Math.sin(i*2.1))),lo=Math.min(o,cl)*(1-.05-.04*Math.abs(Math.cos(i*1.3)));out.push({l:lab(i),o,h:hi,lw:lo,c:cl});prev=cl}return out}
function xSvg(d){const W=600,H=230,pl=44,pr=8,pt=10,pb=26,iw=W-pl-pr,ih=H-pt-pb,mx=Math.max(...d.map(x=>x.h))*1.05,mn=Math.min(...d.map(x=>x.lw))*.9,y=v=>pt+ih-(v-mn)/(mx-mn||1)*ih,bw=iw/d.length;
 const grid=[0,1,2,3].map(i=>{const v=mn+(mx-mn)*i/3;return `<line x1="${pl}" x2="${W-pr}" y1="${y(v)}" y2="${y(v)}" stroke="var(--border)" stroke-dasharray="3 3"/><text x="${pl-6}" y="${y(v)+4}" text-anchor="end" font-size="10" fill="var(--muted)">${UI.xc.metric==='revenue'?'₹'+Math.round(v/1000)+'k':Math.round(v)}</text>`}).join('');
 const xl=d.map((x,i)=>`<text x="${pl+bw*i+bw/2}" y="${H-8}" text-anchor="middle" font-size="10" fill="var(--muted)">${x.l}</text>`).join('');
 if(UI.xc.tab==='graph'){const pts=d.map((x,i)=>`${pl+bw*i+bw/2},${y(x.c)}`).join(' ');return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('Graph view')}: ${t(XM.find(m=>m[0]===UI.xc.metric)[1])}" style="width:100%;height:auto">${grid}${d.map((x,i)=>`<rect data-ci="${i}" tabindex="0" role="img" aria-label="${x.l}: ${xfmt(x.c)}" x="${pl+bw*i+bw*.18}" y="${y(x.c)}" width="${bw*.64}" height="${pt+ih-y(x.c)}" rx="3" fill="var(--primary)" fill-opacity=".85"/>`).join('')}<polyline points="${pts}" fill="none" stroke="var(--secondary)" stroke-width="2.5" stroke-linejoin="round"/>${d.map((x,i)=>`<circle cx="${pl+bw*i+bw/2}" cy="${y(x.c)}" r="3.5" fill="var(--secondary)"/>`).join('')}${xl}</svg>`}
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('Candle view')}: ${t(XM.find(m=>m[0]===UI.xc.metric)[1])}" style="width:100%;height:auto">${grid}${d.map((x,i)=>{const up=x.c>=x.o,cx=pl+bw*i+bw/2,top=y(Math.max(x.o,x.c)),bot=y(Math.min(x.o,x.c)),col=up?'var(--success)':'var(--error)';return `<g data-ci="${i}" tabindex="0" role="img" aria-label="${x.l}: ${up?t('Up'):t('Down')}. ${t('Open')} ${xfmt(x.o)}, ${t('High')} ${xfmt(x.h)}, ${t('Low')} ${xfmt(x.lw)}, ${t('Close')} ${xfmt(x.c)}"><line x1="${cx}" x2="${cx}" y1="${y(x.h)}" y2="${y(x.lw)}" stroke="${col}" stroke-width="2"/><rect x="${cx-bw*.3}" y="${top}" width="${bw*.6}" height="${Math.max(3,bot-top)}" rx="2" fill="${up?col:'var(--surface)'}" stroke="${col}" stroke-width="2.5" ${up?'':'stroke-dasharray="0"'}/>${up?'':`<line x1="${cx-bw*.3+3}" x2="${cx+bw*.3-3}" y1="${(top+bot)/2}" y2="${(top+bot)/2}" stroke="${col}" stroke-width="1.5" opacity=".0"/>`}</g>`}).join('')}${xl}</svg>`}
function chartCard(){const c=UI.xc,d=xData(),city=D().cities.find(x=>x.id===c.city);let body;
 if(S.demo.chartErr)body=errState('We could not load the chart data.');else if(c.load)body=`<div class="stack" aria-busy="true"><div class="skel" style="height:220px"></div><div class="skel" style="height:18px;width:60%"></div></div>`;else if(!d.length)body=empty('📊','No data for '+(city?nm(city):'this city')+' yet',(city?nm(city):'This city')+' is not live, so there are no orders to chart.');
 else body=`<div class="cndl" id="cndl">${xSvg(d)}<div class="tip" id="ctip" role="status"></div></div><div class="row wrap-r" style="gap:16px" aria-label="${t('Legend')}">${c.tab==='candle'?`<span class="small"><svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><rect x="3" y="3" width="12" height="12" rx="2" fill="var(--success)" stroke="var(--success)" stroke-width="2"/></svg> ${t('Up: close ≥ open (filled)')}</span><span class="small"><svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><rect x="3" y="3" width="12" height="12" rx="2" fill="none" stroke="var(--error)" stroke-width="2.5"/></svg> ${t('Down: close < open (hollow)')}</span><span class="small muted">${t('Wick = high to low')}</span>`:`<span class="small"><i style="color:var(--primary)">■</i> ${t(XM.find(m=>m[0]===c.metric)[1])}</span><span class="small"><i style="color:var(--secondary)">●</i> ${t('Trend')}</span>`}</div>`;
 return `<div class="card pad stack"><div class="row between wrap-r"><h3>${t(XM.find(m=>m[0]===c.metric)[1])}</h3>${segBtn('xcTab',c.tab,[['graph','Graph view'],['candle','Candle view']])}</div><div class="grid g3" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))"><div class="field"><label for="xc_m">${t('Metric')}</label><select class="input" id="xc_m" data-chg="xcSet" data-k="metric">${XM.map(([k,l])=>`<option value="${k}" ${c.metric===k?'selected':''}>${t(l)}</option>`).join('')}</select></div><div class="field"><label for="xc_r">${t('Date range')}</label><select class="input" id="xc_r" data-chg="xcSet" data-k="range">${XR.map(([k,l])=>`<option value="${k}" ${c.range===k?'selected':''}>${t(l)}</option>`).join('')}</select></div><div class="field"><label for="xc_c">${t('City')}</label><select class="input" id="xc_c" data-chg="xcSet" data-k="city"><option value="all">${t('All cities')}</option>${D().cities.map(x=>`<option value="${x.id}" ${c.city===x.id?'selected':''}>${esc(nm(x))}</option>`).join('')}</select></div></div>${body}</div>`}
A.xcTab=el=>{UI.xc.tab=el.dataset.v;UI.xc.load=true;render(true);setTimeout(()=>{UI.xc.load=false;render(true)},260)};
CH.xcSet=el=>{UI.xc[el.dataset.k]=el.value;UI.xc.load=true;render(true);setTimeout(()=>{UI.xc.load=false;render(true)},260)};
function tipShow(g){const d=xData()[+g.dataset.ci];if(!d)return;const tip=$('#ctip'),box=$('#cndl');if(!tip)return;const up=d.c>=d.o,r=g.getBoundingClientRect(),b=box.getBoundingClientRect();tip.innerHTML=UI.xc.tab==='candle'?`<b>${d.l}: ${up?t('Up'):t('Down')}</b><br>${t('Open')} ${xfmt(d.o)}<br>${t('High')} ${xfmt(d.h)}<br>${t('Low')} ${xfmt(d.lw)}<br>${t('Close')} ${xfmt(d.c)}`:`<b>${d.l}</b><br>${xfmt(d.c)}`;tip.style.display='block';tip.style.left=clamp(r.left-b.left+r.width/2-75,0,b.width-160)+'px';tip.style.top=Math.max(0,r.top-b.top-(UI.xc.tab==='candle'?110:50))+'px'}
document.addEventListener('pointerover',e=>{const g=e.target.closest&&e.target.closest('[data-ci]');if(g)tipShow(g)});document.addEventListener('focusin',e=>{const g=e.target.closest&&e.target.closest('[data-ci]');if(g)tipShow(g)});document.addEventListener('pointerdown',e=>{const g=e.target.closest&&e.target.closest('[data-ci]');if(g)tipShow(g);else{const t_=$('#ctip');t_&&(t_.style.display='none')}});
const _xh=V.xhome;V.xhome=()=>{const h=_xh();return h.replace(/<div class="cols2 eq"><div class="card pad stack"><h3>[^<]*GMV[\s\S]*?<\/div><div class="card pad stack"><div class="row between"><h3>/,m=>`<div class="stack">${chartCard()}</div><div class="cols2 eq"><div class="card pad stack"><div class="row between"><h3>`)};
/* ---- A2 categories ---- */
const superOnly=fn=>function(el){if(S.role!=='super'){toast(t('Only Super Admin can change main categories'),'lock');return}return fn(el)};
['catEdit','catMove'].forEach(k=>{const f=A[k];A[k]=superOnly(f)});const _con=CH.catOn;CH.catOn=el=>{if(S.role!=='super'){el.checked=!el.checked;toast(t('Only Super Admin can change main categories'),'lock');return}_con(el)};
V.acats=()=>gate('catalog',()=>{const tab=UI.act||'cats',l=D()[tab],sup=S.role==='super',pend=D().subs.filter(s=>s.status==='pending').length;
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Categories')}</h1><div class="row wrap-r"><a class="btn o sm" href="#asubs">${ic('list',16)} ${t('Subcategory suggestions')} ${pend?`<span class="cnt">${pend}</span>`:''}</a>${sup?`<button class="btn p sm" data-act="catEdit" data-id="">${ic('plus',16)} ${t('Add main category')}</button>`:''}</div></div>
 ${sup?alertBox('info',t('Main categories are a fixed, standard list. Only you (Super Admin) can add, rename, reorder or deactivate them. Vendors and providers can only suggest subcategories.'),'lock'):alertBox('warn',t('Main categories are managed by Super Admin only. You can review subcategory suggestions and suggest new ones.'),'lock')}
 <div class="tabs">${[['cats','Product categories'],['scats','Service categories']].map(([k,lb])=>`<button class="${tab===k?'on':''}" data-act="act" data-v="${k}">${t(lb)}</button>`).join('')}</div>
 <div class="stack">${l.map((c,i)=>{const subs=tab==='scats'?svcSubs(c.id).map(x=>subLabel(x.slug)):subsFor(c.id);return `<div class="card pad stack"><div class="row"><div class="art mini" style="--h:${c.h}">${c.e}</div><div class="grow"><b>${esc(c.en)}</b> ${sup?'':`<span class="badge neu">${ic('lock',12)} ${t('Fixed')}</span>`}<div class="small t2">${esc(c.hi)}</div></div><span class="toggle"><input type="checkbox" ${c.on?'checked':''} data-chg="catOn" data-id="${c.id}" ${sup?'':'disabled'} aria-label="${t('Active')}"><span></span></span><button class="iconbtn" data-act="catMove" data-i="${i}" data-d="-1" ${i&&sup?'':'disabled'} aria-label="${t('Move up')}">${ic('cu',18)}</button><button class="iconbtn" data-act="catMove" data-i="${i}" data-d="1" ${i<l.length-1&&sup?'':'disabled'} aria-label="${t('Move down')}">${ic('cd',18)}</button>${sup?`<button class="btn g sm" data-act="catEdit" data-id="${c.id}">${t('Edit')}</button>`:''}</div><div class="row wrap-r" style="gap:6px"><span class="xs muted">${t('Subcategories')}:</span>${subs.map(s=>`<span class="chip" style="min-height:30px;font-size:.8rem">${esc(s)}</span>`).join('')||`<span class="xs muted">${t('None yet')}</span>`}<button class="btn t sm" data-act="adSubSuggest" data-main="${c.id}">${ic('plus',14)} ${t('Suggest')}</button>${tab==='scats'?`<button class="btn o sm" data-act="acPreview" data-id="${c.id}">${ic('eye',14)} ${t('Preview filter')}</button>`:''}</div></div>`}).join('')}</div></div>`});
A.adSubSuggest=el=>subSheet({main:el.dataset.main});
const SUBF=[['pending','Pending'],['approved','Approved'],['rejected','Rejected'],['merged','Merged'],['all','All']];
V.asubs=()=>gate('catalog',()=>{const f=UI.asf2||'pending',l=D().subs.filter(s=>f==='all'||s.status===f).sort((a,b)=>b.ts-a.ts);
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Subcategory suggestions')}</h1><button class="btn g sm" data-act="adSubSuggest" data-main="grocery">${ic('plus',16)} ${t('Suggest as admin')}</button></div><div class="chips">${SUBF.map(([k,lb])=>`<button class="chip ${f===k?'on':''}" data-act="asf2" data-v="${k}">${t(lb)} (${k==='all'?D().subs.length:D().subs.filter(s=>s.status===k).length})</button>`).join('')}</div>
 ${l.length?`<div class="stack">${l.map(s=>{const sim=D().subs.concat(D().products.filter(p=>p.cat===s.main).map(p=>({id:'x'+p.id,en:p.sub,main:s.main,status:'approved'}))).find(o=>o.id!==s.id&&o.main===s.main&&o.status!=='rejected'&&(o.en.toLowerCase()===s.en.toLowerCase()||o.en.toLowerCase().includes(s.en.toLowerCase())||s.en.toLowerCase().includes(o.en.toLowerCase())||lev(o.en,s.en)<=2));return `<div class="card pad stack"><div class="row between wrap-r"><div><b>${esc(s.en)}</b> ${s.hi?`<span class="small t2">(${esc(s.hi)})</span>`:''}<div class="small t2">${esc(catName(s.main))} · ${t('Suggested by')} ${esc(s.by)} (${t(s.byRole)}) · ${ago(s.ts)}</div></div>${subBadge(s.status)}</div>${s.note?`<div class="small">“${esc(s.note)}”</div>`:''}${s.reason?`<div class="small t2">${t('Reason')}: ${esc(s.reason)}</div>`:''}${s.mergedInto?`<div class="small t2">${t('Merged into')}: ${esc(s.mergedInto)}</div>`:''}${sim&&s.status==='pending'?alertBox('warn',`${t('Similar subcategory already exists')}: <b>${esc(sim.en)}</b>`,'info'):''}${s.status==='pending'?`<div class="row wrap-r"><button class="btn p sm" data-act="subAp" data-id="${s.id}" ${dis('catalog')}>${ic('check',14)} ${t('Approve')}</button><button class="btn g sm" data-act="subRej" data-id="${s.id}" ${dis('catalog')}>${ic('x',14)} ${t('Reject')}</button><button class="btn g sm" data-act="subMerge" data-id="${s.id}" ${dis('catalog')}>${ic('merge',14)} ${t('Merge into existing')}</button></div>`:''}</div>`}).join('')}</div>`:empty('✅','No suggestions here','New suggestions from vendors and providers will appear here.')}</div>`});
A.asf2=el=>{UI.asf2=el.dataset.v;render(true)};
const notifySug=(s,title,body)=>{if(s.byRole==='vendor'||s.byRole==='provider')notify(s.byRole,title,body,s.byRole==='vendor'?'vproducts':'sproducts','admin')};
A.subAp=el=>{const s=D().subs.find(x=>x.id===el.dataset.id);s.status='approved';notifySug(s,'Subcategory approved','“'+s.en+'” is now available under '+catName(s.main)+'.');audit('Subcategory approved',s.en,{status:'pending'},{status:'approved'});save();render(true);toast(t('Approved. The suggester was notified.'),'check')};
A.subRej=el=>sheet(`<h3>${t('Reject suggestion')}</h3><form data-form="subRej" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('Reason (sent to the suggester)','reason','',{type:'textarea',req:1})}<button class="btn d">${t('Reject suggestion')}</button></form>`);
F.subRej=d=>{const s=D().subs.find(x=>x.id===d.id);s.status='rejected';s.reason=d.reason;notifySug(s,'Subcategory rejected','“'+s.en+'”: '+d.reason);audit('Subcategory rejected',s.en,{status:'pending'},{status:'rejected',reason:d.reason});save();closeSheet();render(true);toast(t('Rejected. The suggester was notified.'))};
A.subMerge=el=>{const s=D().subs.find(x=>x.id===el.dataset.id);sheet(`<h3>${t('Merge into existing')}</h3><p class="small t2">“${esc(s.en)}” ${t('will be treated as the same as the one you pick.')}</p><form data-form="subMerge" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${s.id}">${field('Existing subcategory','into',subsFor(s.main)[0]||'',{type:'select',opts:(subsFor(s.main).length?subsFor(s.main):allSubs()).map(x=>[x,x])})}<button class="btn p">${t('Merge')}</button></form>`)};
F.subMerge=d=>{const s=D().subs.find(x=>x.id===d.id);s.status='merged';s.mergedInto=d.into;notifySug(s,'Subcategory merged','“'+s.en+'” was merged into “'+d.into+'”.');audit('Subcategory merged',s.en+' → '+d.into,{},{});save();closeSheet();render(true);toast(t('Merged'),'merge')};
/* ---- A3 admins & areas ---- */
UI.xad={q:'',city:'',area:'',role:'',status:'',open:{}};
const adFilter=()=>{const f=UI.xad,q=f.q.toLowerCase();return D().admins.filter(a=>(!q||(a.name+a.phone+a.email).toLowerCase().includes(q))&&(!f.city||a.cities.includes(f.city))&&(!f.area||(f.area.startsWith('z:')?(D().zones.find(z=>z.id===f.area.slice(2))||{}).city&&a.cities.includes(D().zones.find(z=>z.id===f.area.slice(2)).city)&&a.areas.length>0:a.areas.includes(f.area)))&&(!f.role||a.role===f.role)&&(!f.status||a.status===f.status))};
const adChips=()=>{const f=UI.xad,o=[];if(f.city)o.push(['city',nm(D().cities.find(c=>c.id===f.city))]);if(f.area)o.push(['area',f.area.startsWith('z:')?(D().zones.find(z=>z.id===f.area.slice(2))||{}).name:nm(areaOf(f.area))]);if(f.role)o.push(['role',f.role]);if(f.status)o.push(['status',t(f.status==='active'?'Active':'Inactive')]);return o};
const adFilters=()=>{const f=UI.xad;const sel=(k,l,opts)=>`<div class="field"><label for="ad_${k}">${t(l)}</label><select class="input" id="ad_${k}" data-chg="adf" data-k="${k}">${opts.map(o=>`<option value="${esc(o[0])}" ${f[k]===o[0]?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`;
 return sel('city','City',[['','All cities'],...D().cities.map(c=>[c.id,nm(c)])])+sel('area','Area / zone',[['','All areas & zones'],...AREAS.map(a=>[a.id,'📍 '+nm(a)]),...D().zones.map(z=>['z:'+z.id,'▭ '+z.name])])+sel('role','Role',[['','All roles'],...S.roles.map(r=>[r.name,r.name])])+sel('status','Status',[['','Any status'],['active','Active'],['inactive','Inactive']])};
const adCard=a=>{const open=!!UI.xad.open[a.id],act=a.status==='active',zs=D().zones.filter(z=>a.cities.includes(z.city));
 const chipsMin=[...a.cities.map(c=>nm(D().cities.find(x=>x.id===c)||{en:c})),...a.areas.slice(0,2).map(x=>nm(areaOf(x)))];
 return `<div class="acard ${open?'open':''}"><button class="hd" data-act="adOpen" data-id="${a.id}" aria-expanded="${open}" aria-controls="adb_${a.id}"><div class="art mini" style="border-radius:50%;--h:${a.id.charCodeAt(2)*40}">${esc(a.name.split(' ').pop()[0])}</div><div class="grow" style="min-width:0"><b class="truncate" style="display:block">${esc(a.name)}</b><div class="row wrap-r" style="gap:4px;margin-top:2px"><span class="badge sec">${esc(a.role)}</span>${chipsMin.map(c=>`<span class="badge neu">${esc(c)}</span>`).join('')}${a.areas.length>2?`<span class="badge neu">+${a.areas.length-2}</span>`:''}</div></div><span class="badge ${act?'ok':'neu'}">${act?'●':'○'} ${t(act?'Active':'Inactive')}</span><span class="chev">${ic('cd',20)}</span></button>
 ${open?`<div class="bd" id="adb_${a.id}"><dl class="kv"><dt>${t('Phone')}</dt><dd><a href="${telH(a.phone)}">+91 ${esc(a.phone)}</a></dd><dt>Email</dt><dd>${esc(a.email)}</dd><dt>${t('Last active')}</dt><dd>${ago(a.last)}</dd></dl>
 <div><div class="lbl small">${t('Assigned cities & zones')}</div><div class="row wrap-r" style="gap:6px;margin-top:4px">${a.cities.map(c=>`<span class="chip" style="min-height:32px">${esc(nm(D().cities.find(x=>x.id===c)||{en:c}))}</span>`).join('')}${zs.map(z=>`<span class="chip" style="min-height:32px">▭ ${esc(z.name)}</span>`).join('')}${a.areas.map(x=>`<span class="chip" style="min-height:32px">📍 ${esc(nm(areaOf(x)))}</span>`).join('')||''}</div></div>
 <div><div class="lbl small">${t('Permissions summary')}</div><div class="row wrap-r" style="gap:6px;margin-top:4px">${MODS.map(([k,l])=>{const p=a.perms[k]||[];return `<span class="badge ${p.includes('edit')?'ok':p.includes('view')?'info':'neu'}">${t(l)}: ${p.includes('edit')?t('Edit'):p.includes('view')?t('View'):t('None')}</span>`}).join('')}</div></div>
 <div class="row wrap-r"><a class="btn g sm" href="#xactivity" data-act="adAudit" data-n="${esc(a.name)}">${ic('doc',14)} ${t('Audit log')}</a><button class="btn g sm" data-act="adAreas" data-id="${a.id}">${ic('map',14)} ${t('Edit areas')}</button><button class="btn g sm" data-act="adPerms" data-id="${a.id}">${ic('lock',14)} ${t('Permissions')}</button><span class="grow"></span><button class="btn ${act?'d':'p'} sm" data-act="adSwitch" data-id="${a.id}">${act?t('Deactivate'):t('Activate')}</button></div></div>`:''}</div>`};
V.xadmins=()=>{const l=adFilter(),f=UI.xad,chips=adChips();post.push(()=>{});
 return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Admins & areas')}</h1><button class="btn p sm" data-act="adNew">${ic('plus',16)} ${t('Add admin')}</button></div>
 <div class="card pad stack"><div class="searchbar">${ic('search',18)}<input data-in="adq" value="${esc(f.q)}" placeholder="${t('Search name, phone or email')}" aria-label="${t('Search admins')}"></div><div class="fdesk">${adFilters()}</div><button class="btn g sm fmob" data-act="adSheet" style="justify-self:start">${ic('filter',16)} ${t('Filters')}${chips.length?` <span class="cnt">${chips.length}</span>`:''}</button></div>
 <div id="adres" class="stack">${adRes()}</div></div>`};
function adRes(){const l=adFilter(),chips=adChips();return `<div class="row between wrap-r"><b aria-live="polite">${l.length} ${t(l.length===1?'admin':'admins')}</b>${chips.length||UI.xad.q?`<button class="btn t sm" data-act="adClear">${t('Clear all')}</button>`:''}</div>${chips.length?`<div class="row wrap-r" style="gap:6px">${chips.map(([k,lb])=>`<button class="rchip" data-act="adRm" data-k="${k}" aria-label="${t('Remove filter')}: ${esc(lb)}">${esc(lb)} <b>${ic('x',14)}</b></button>`).join('')}</div>`:''}${l.length?l.map(adCard).join(''):empty('🔎','No admins match','Try a different name, or clear the filters.','<button class="btn p" data-act="adClear">'+t('Clear all')+'</button>')}`}
INP.adq=v=>{UI.xad.q=v;$('#adres').innerHTML=adRes()};CH.adf=el=>{UI.xad[el.dataset.k]=el.value;render(true)};A.adRm=el=>{UI.xad[el.dataset.k]='';render(true)};A.adClear=()=>{UI.xad={q:'',city:'',area:'',role:'',status:'',open:UI.xad.open};closeSheet();render(true)};
A.adOpen=el=>{UI.xad.open[el.dataset.id]=!UI.xad.open[el.dataset.id];render(true)};A.adAudit=el=>{UI.xaq=el.dataset.n};
A.adSheet=()=>sheet(`<div class="row between"><h3>${t('Filters')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="stack" style="margin-top:10px">${adFilters()}<div class="row"><button class="btn g grow" data-act="adClear">${t('Clear all')}</button><button class="btn p grow" data-act="closeSheet">${t('Show')} ${adFilter().length}</button></div></div>`);
const _adf=CH.adf;CH.adf=el=>{UI.xad[el.dataset.k]=el.value;const sh=$('#sheetRoot');if(sh){$('#adres')&&($('#adres').innerHTML=adRes());const b=sh.querySelector('.btn.p');b&&(b.textContent=t('Show')+' '+adFilter().length)}else render(true)};
A.adSwitch=el=>{const a=D().admins.find(x=>x.id===el.dataset.id),on=a.status==='active';confirmBox(on?`${t('Deactivate')} ${a.name}?`:`${t('Activate')} ${a.name}?`,on?`${a.name} ${t('will lose access immediately. Their')} ${a.areas.length} ${t('assigned areas will have no admin until reassigned. Signed-in sessions end now.')}`:`${a.name} ${t('will be able to sign in again and manage their assigned areas.')}`,on?t('Confirm deactivate'):t('Confirm activate'),()=>{const b=a.status;a.status=on?'inactive':'active';audit('Admin '+a.status,a.name,{status:b},{status:a.status});save();render(true);toast(`${a.name} ${on?t('was deactivated'):t('was activated')}`,'check')},on)};
A.adAreas=el=>{const a=D().admins.find(x=>x.id===el.dataset.id);sheet(`<div class="row between"><h3>${t('Areas for')} ${esc(a.name)}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="chips" style="flex-wrap:wrap;margin-top:10px">${AREAS.map(x=>`<button class="chip ${a.areas.includes(x.id)?'on':''}" data-act="adArea2" data-id="${a.id}" data-a="${x.id}" aria-pressed="${a.areas.includes(x.id)}">${esc(nm(x))}</button>`).join('')}</div>`,{label:'Areas'})};
A.adArea2=el=>{A.adArea(el);A.adAreas({dataset:{id:el.dataset.id}})};
A.adPerms=el=>{const a=D().admins.find(x=>x.id===el.dataset.id);sheet(`<div class="row between"><h3>${t('Permissions')}: ${esc(a.name)}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="perm" style="grid-template-columns:1.6fr repeat(2,1fr);margin-top:10px;min-width:0"><div class="h n">${t('Module')}</div><div class="h">${t('View')}</div><div class="h">${t('Edit')}</div>${MODS.map(([k,lb])=>`<div class="n">${t(lb)}</div>${PERM_ACTS.map(p=>`<div><input type="checkbox" ${(a.perms[k]||[]).includes(p)?'checked':''} data-chg="adPerm2" data-id="${a.id}" data-m="${k}" data-p="${p}" aria-label="${t(lb)} ${p}" style="width:20px;height:20px;accent-color:var(--primary)"></div>`).join('')}`).join('')}</div>`,{label:'Permissions'})};
CH.adPerm2=el=>{CH.adPerm(el);A.adPerms({dataset:{id:el.dataset.id}})};
F.adNew=d=>{D().admins.push({id:rid('ad'),name:d.name,email:d.email,phone:'9876500000',role:'Support',cities:['padrauna'],last:Date.now(),scopes:['zone'],areas:[],status:'active',perms:{approvals:['view'],orders:['view'],users:[],reviews:[],comms:[],reports:['view'],catalog:[],promos:[]}});audit('Created admin',d.name,{},{});save();closeSheet();render(true);toast(t('Admin created'),'check')};
/* ---- A4 roles ---- */
UI.rl={edit:null};
const mxStr=m=>MODS.map(([k,l])=>`${t(l)}: ${(m[k]||'')||'—'}`);
const RACT_L={v:'View',c:'Create',e:'Edit',d:'Delete',x:'Export'};
const mxText=s=>s?[...s].map(c=>RACT_L[c]||c).join(', '):'None';
V.xroles=()=>{const e=UI.rl.edit;if(e)return roleEditor();
 return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Roles & permissions')}</h1><button class="btn p sm" data-act="rlNew">${ic('plus',16)} ${t('New role')}</button></div><div class="stack">${S.roles.map(r=>{const n=D().admins.filter(a=>a.role===r.name).length;return `<div class="card pad stack"><div class="row between wrap-r"><div><b>${esc(r.name)}</b> ${r.system?`<span class="badge neu">${ic('lock',12)} ${t('System role')}</span>`:''}<div class="small t2">${esc(r.desc||'')}</div></div><span class="badge info">${n} ${t(n===1?'admin':'admins')}</span></div><div class="row wrap-r" style="gap:6px">${MODS.map(([k,l])=>(r.mx[k]||'')?`<span class="badge sec">${t(l)}: ${mxText(r.mx[k])}</span>`:'').join('')||`<span class="muted small">${t('No permissions')}</span>`}</div><div class="row wrap-r"><button class="btn g sm" data-act="rlEdit" data-id="${r.id}">${ic('edit',14)} ${t('Edit')}</button><button class="btn g sm" data-act="rlDup" data-id="${r.id}">${ic('copy',14)} ${t('Duplicate')}</button><button class="btn ${r.system?'g':'d'} sm" data-act="rlDel" data-id="${r.id}" ${r.system?'disabled title="'+t('System roles cannot be deleted')+'"':''}>${r.system?ic('lock',14):ic('trash',14)} ${t('Delete')}</button></div></div>`}).join('')}</div></div>`};
function roleEditor(){const e=UI.rl.edit,r=S.roles.find(x=>x.id===e.id),dirty=JSON.stringify(e.draft)!==JSON.stringify(e.orig);
 return `<div class="stack-lg"><button class="btn t sm" data-act="rlBack" style="justify-self:start">${ic('cl',16)} ${t('All roles')}</button><div class="row between wrap-r"><h1>${t('Edit role')}</h1><span id="rlst" role="status" class="badge ${dirty?'warn':'neu'}">${dirty?'● '+t('Unsaved changes'):t('No changes')}</span></div>${r.system?alertBox('info',t('System role: you can edit permissions but the name is locked and the role cannot be deleted.'),'lock'):''}
 <div class="card pad stack"><div class="field"><label for="rl_n">${t('Role name')}</label><input class="input" id="rl_n" value="${esc(e.draft.name)}" data-in="rlf" data-k="name" ${r.system?'disabled':''}></div><div class="field"><label for="rl_d">${t('Description')}</label><textarea class="input" id="rl_d" data-in="rlf" data-k="desc">${esc(e.draft.desc)}</textarea></div></div>
 <div class="table-w"><div class="perm" style="grid-template-columns:1.6fr repeat(5,1fr)"><div class="h n">${t('Module')}</div>${RACTS.map(a=>`<div class="h">${t(a[1])}</div>`).join('')}${MODS.map(([k,lb])=>`<div class="n">${t(lb)}</div>${RACTS.map(([c,cl])=>`<div><input type="checkbox" ${(e.draft.mx[k]||'').includes(c)?'checked':''} data-chg="rlp" data-m="${k}" data-c="${c}" aria-label="${t(lb)} ${t(cl)}" style="width:20px;height:20px;accent-color:var(--primary)"></div>`).join('')}`).join('')}</div></div>
 <div class="row"><button class="btn g grow" data-act="rlBack">${t('Discard')}</button><button class="btn p grow" data-act="rlSave" ${dirty?'':'disabled'}>${t('Review & save')}</button></div></div>`}
A.rlEdit=el=>{const r=S.roles.find(x=>x.id===el.dataset.id);const d={name:r.name,desc:r.desc||'',mx:JSON.parse(JSON.stringify(r.mx))};UI.rl.edit={id:r.id,draft:d,orig:JSON.parse(JSON.stringify(d))};render()};
A.rlBack=()=>{if(UI.rl.edit&&JSON.stringify(UI.rl.edit.draft)!==JSON.stringify(UI.rl.edit.orig)&&!UI.rl.disc){return confirmBox(t('Discard changes?'),t('Your edits to this role will be lost.'),t('Discard'),()=>{UI.rl.edit=null;render()},true)}UI.rl.edit=null;render()};
INP.rlf=(v,el)=>{UI.rl.edit.draft[el.dataset.k]=v;const d=JSON.stringify(UI.rl.edit.draft)!==JSON.stringify(UI.rl.edit.orig);const b=$('[data-act=rlSave]');if(b)b.disabled=!d;const bd=$('#rlst');if(bd){bd.className='badge '+(d?'warn':'neu');bd.textContent=d?'● '+t('Unsaved changes'):t('No changes')}};
CH.rlp=el=>{const m=UI.rl.edit.draft.mx,k=el.dataset.m,c=el.dataset.c;let s=m[k]||'';s=el.checked?(s.includes(c)?s:s+c):s.replace(c,'');if(c!=='v'&&el.checked&&!s.includes('v'))s+='v';if(c==='v'&&!el.checked)s='';m[k]=s;render(true)};
A.rlSave=()=>{const e=UI.rl.edit,o=e.orig,d=e.draft,ch=[];if(o.name!==d.name)ch.push([t('Name'),o.name,d.name]);if(o.desc!==d.desc)ch.push([t('Description'),o.desc||'—',d.desc||'—']);MODS.forEach(([k,l])=>{if((o.mx[k]||'')!==(d.mx[k]||''))ch.push([t(l),mxText(o.mx[k]||''),mxText(d.mx[k]||'')])});
 sheet(`<h3>${t('Review changes')}</h3><div class="stack" style="margin-top:10px">${ch.map(c=>`<div class="card pad"><b class="small">${esc(c[0])}</b><div class="row wrap-r small" style="gap:8px"><span class="badge neu">${t('Before')}: ${esc(c[1])}</span><span>→</span><span class="badge ok">${t('After')}: ${esc(c[2])}</span></div></div>`).join('')||`<span class="muted">${t('No changes')}</span>`}<div class="row"><button class="btn g grow" data-act="closeSheet">${t('Keep editing')}</button><button class="btn p grow" data-act="rlConfirm">${t('Confirm & save')}</button></div></div>`,{label:'Review changes'})};
A.rlConfirm=()=>{const e=UI.rl.edit,r=S.roles.find(x=>x.id===e.id),old=r.name;audit('Role updated',old,{mx:e.orig.mx,name:e.orig.name},{mx:e.draft.mx,name:e.draft.name});r.name=e.draft.name;r.desc=e.draft.desc;r.mx=e.draft.mx;D().admins.forEach(a=>{if(a.role===old)a.role=r.name});save();UI.rl.edit=null;closeSheet();render();toast(t('Role saved'),'check')};
A.rlNew=()=>sheet(`<h3>${t('New role')}</h3><form data-form="rlNew" class="stack" style="margin-top:10px">${field('Role name','n','',{req:1})}${field('Description','d','')}<button class="btn p">${t('Create role')}</button></form>`);
F.rlNew=d=>{if(S.roles.some(r=>r.name.toLowerCase()===d.n.trim().toLowerCase())){toast(t('A role with this name already exists'),'alert');return}S.roles.push({id:rid('rl'),name:d.n.trim(),desc:d.d,system:false,mx:Object.fromEntries(MODS.map(([k])=>[k,'']))});audit('Role created',d.n,{},{});save();closeSheet();render(true);toast(t('Role created'),'check')};
A.rlDup=el=>{const r=S.roles.find(x=>x.id===el.dataset.id);let n=r.name+' (copy)',i=2;while(S.roles.some(x=>x.name===n))n=r.name+' (copy '+(i++)+')';S.roles.push({id:rid('rl'),name:n,desc:r.desc,system:false,mx:JSON.parse(JSON.stringify(r.mx))});audit('Role duplicated',r.name+' → '+n,{},{});save();render(true);toast(t('Role duplicated'),'copy')};
A.rlDel=el=>{const r=S.roles.find(x=>x.id===el.dataset.id);if(r.system){toast(t('System roles cannot be deleted'),'lock');return}const as=D().admins.filter(a=>a.role===r.name);
 if(as.length)return sheet(`<h3>${t('Reassign')} ${as.length} ${t(as.length===1?'admin':'admins')} ${t('first')}</h3><div class="alert bad" style="margin-top:10px">${ic('alert',20)}<div><b>${t('Can’t delete')} “${esc(r.name)}”.</b> ${as.map(a=>esc(a.name)).join(', ')} ${t('still use this role.')}</div></div><form data-form="rlReassign" class="stack" style="margin-top:12px"><input type="hidden" name="id" value="${r.id}">${field('Move these admins to','to',S.roles.find(x=>x.id!==r.id).name,{type:'select',opts:S.roles.filter(x=>x.id!==r.id).map(x=>[x.name,x.name])})}<button class="btn d">${t('Reassign & delete role')}</button></form>`,{label:'Reassign admins'});
 confirmBox(`${t('Delete role')} “${r.name}”?`,t('No admins use this role. This cannot be undone.'),t('Delete role'),()=>{S.roles=S.roles.filter(x=>x.id!==r.id);audit('Role deleted',r.name,{},{});save();render(true);toast(t('Role deleted'),'trash')},true)};
F.rlReassign=d=>{const r=S.roles.find(x=>x.id===d.id);D().admins.forEach(a=>{if(a.role===r.name)a.role=d.to});S.roles=S.roles.filter(x=>x.id!==r.id);audit('Role deleted (admins reassigned)',r.name+' → '+d.to,{},{});save();closeSheet();render(true);toast(t('Admins reassigned. Role deleted.'),'check')};
